age = 20

if age >= 18:
    print('Adult')
else:
    print('Minor')
# → Adult

# Multiple conditions with elif
score = 75

if score >= 90:
    grade = 'A'
elif score >= 80:
    grade = 'B'
elif score >= 70:
    grade = 'C'
elif score >= 60:
    grade = 'D'
else:
    grade = 'F'

print(f'Grade: {grade}')  # Grade: C

# These are ALL falsy
if not 0:      print('0 is falsy')
if not '':     print('empty string is falsy')
if not []:     print('empty list is falsy')
if not {}:     print('empty dict is falsy')
if not None:   print('None is falsy')

# Practical use: check if a value exists
name = ''
if name:
    print(f'Hello, {name}')
else:
    print('No name provided')
# → No name provided

# Check multiple conditions
password = 'abc123'
if len(password) >= 8 and any(c.isdigit() for c in password):
    print('Password is strong')
else:
    print('Password too weak')
# → Password too weak (length < 8)
